const FAQ_WORD_COUNT = US_ENTRY_FAQ.reduce(
  (sum, item) => sum + countWords(item.question) + countWords(item.answer),
  0,
);

/** Article words: summary + narrative + FAQ. The bibliography is excluded from the band. */
export const US_ENTRY_WORD_COUNT =
  countWords(US_ENTRY_EXECUTIVE_SUMMARY_HTML) + countWords(NARRATIVE_HTML) + FAQ_WORD_COUNT;

const READING_WORDS_PER_MINUTE = 225;

export const US_ENTRY_READING_TIME = Math.ceil(
  (countWords(US_ENTRY_EXECUTIVE_SUMMARY_HTML) + countWords(NARRATIVE_HTML) + FAQ_WORD_COUNT) /
    READING_WORDS_PER_MINUTE,
);

